    CHeroExperienceDef* def = (CHeroExperienceDef*)calloc(1, sizeof(CHeroExperienceDef));
    hero->PDef = def;
    Node* head = (Node*)malloc(sizeof(Node)); head->Next = head->Prev = head;
    hero->AttackHistory._Myhead = head;
    CAttackHistoryCombo combos[4];
